import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../repositories/providers.dart';

class OnboardingScreen extends ConsumerStatefulWidget { const OnboardingScreen({super.key}); @override ConsumerState<OnboardingScreen> createState()=>_OnboardingScreenState(); }
class _OnboardingScreenState extends ConsumerState<OnboardingScreen>{ final c=PageController(); int page=0; final data=const [('Everything you need, in one place','Access useful everyday tools, prices, opportunities, alerts, and information.',Icons.apps_outlined),('Built around your community','Discover local information submitted and verified by users, Zaylo AI, and administrators.',Icons.groups_outlined),('Simple, useful and personal','Choose the services that matter to you and personalise your Zaylo experience.',Icons.tune_outlined)]; void done(){ref.read(onboardingCompleteProvider.notifier).state=true; context.go('/welcome');} @override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:Column(children:[Align(alignment:Alignment.centerRight, child:TextButton(onPressed:done, child:const Text('Skip'))), Expanded(child:PageView(controller:c,onPageChanged:(v)=>setState(()=>page=v),children:[for(final item in data) Padding(padding:const EdgeInsets.all(28), child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(item.$3,size:92,color:Theme.of(context).colorScheme.primary), const SizedBox(height:28), Text(item.$1,textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium), const SizedBox(height:12), Text(item.$2,textAlign:TextAlign.center,style:Theme.of(context).textTheme.bodyLarge)]))])), Row(mainAxisAlignment:MainAxisAlignment.center,children:List.generate(3,(i)=>Container(width:page==i?22:8,height:8,margin:const EdgeInsets.all(4),decoration:BoxDecoration(color:page==i?Theme.of(context).colorScheme.primary:Colors.grey,borderRadius:BorderRadius.circular(8))))), Padding(padding:const EdgeInsets.all(20), child:ElevatedButton(onPressed: page==2?done:()=>c.nextPage(duration:const Duration(milliseconds:250),curve:Curves.easeOut), child:Text(page==2?'Get Started':'Next')))])));
}
